const $=id=>document.getElementById(id);
const subjects=[['剑','sword'],['锤子','hammer'],['平底锅','frying pan'],['扫把','broom'],['羽毛球拍','badminton racket'],['马桶搋子','toilet plunger'],['辣条','spicy gluten snack stick'],['卷起来的试卷','rolled examination paper'],['苍蝇拍','fly swatter'],['巨型铅笔','giant pencil']];
const template=s=>`A single ${s}, usable as a handheld melee weapon, isolated object, complete silhouette, stylized game prop, simple clean geometry, solid material, no character, no background, no text.`;
let state={version:1,samples:[],waits:[]},db,current=null,run=null,pending=null,reviewOrder=[];
const toast=s=>{ $('toast').textContent=s;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',3500)};
const request=indexedDB.open('huagechuizi-lab',1);request.onupgradeneeded=()=>request.result.createObjectStore('state');
const ready=new Promise((resolve,reject)=>{request.onsuccess=()=>{db=request.result;const r=db.transaction('state').objectStore('state').get('lab');r.onsuccess=()=>{if(r.result)state=r.result;resolve()};r.onerror=reject};request.onerror=reject});
async function persist(){return new Promise((resolve,reject)=>{const t=db.transaction('state','readwrite');t.objectStore('state').put(state,'lab');t.oncomplete=resolve;t.onerror=()=>reject(t.error)})}
const safe=fn=>(...args)=>Promise.resolve().then(()=>fn(...args)).catch(e=>{console.error(e);toast('未完成：'+e.message)});
const save=()=>persist().catch(e=>{toast('保存失败，请立即导出备份：'+e.message);throw e});
function download(name,data,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function readFile(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('文件读取失败'));r.readAsDataURL(file)})}
function show(tab){document.querySelectorAll('main>section').forEach(s=>s.hidden=s.id!==tab);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));if(tab==='review')review();if(tab==='report')report()}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>show(b.dataset.tab));
subjects.forEach(([zh,en])=>$('subject').add(new Option(zh,en)));
$('subject').onchange=()=>{$('prompt').value=template($('subject').value)};$('subject').onchange();
$('copyPrompt').onclick=safe(async()=>{try{await navigator.clipboard.writeText($('prompt').value);toast('提示词已复制')}catch{ $('prompt').focus();$('prompt').select();toast('请长按复制已选中的提示词')}});
const canvas=$('drawing'),ctx=canvas.getContext('2d');let drawing=false,history=[],hasInk=false;
function white(){ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height)}white();
function snapshot(){history.push({data:ctx.getImageData(0,0,800,500),ink:hasInk});if(history.length>20)history.shift()}
function point(e){const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)*800/r.width,(e.clientY-r.top)*500/r.height]}
canvas.onpointerdown=e=>{if(drawing)return;e.preventDefault();snapshot();drawing=true;hasInk=true;canvas.setPointerCapture(e.pointerId);ctx.lineWidth=5;ctx.strokeStyle='#253b25';ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(...point(e));ctx.lineTo(point(e)[0]+.1,point(e)[1]+.1);ctx.stroke()};
canvas.onpointermove=e=>{if(!drawing)return;e.preventDefault();ctx.lineTo(...point(e));ctx.stroke()};canvas.onpointerup=canvas.onpointercancel=()=>drawing=false;
$('undo').onclick=()=>{const s=history.pop();if(s){ctx.putImageData(s.data,0,0);hasInk=s.ink}};
$('clear').onclick=()=>{snapshot();white();hasInk=false};
$('sketch').onchange=safe(async e=>{const file=e.target.files[0];if(!file)return;const img=new Image();img.src=await readFile(file);await img.decode();snapshot();white();const scale=Math.min(800/img.width,500/img.height);ctx.drawImage(img,(800-img.width*scale)/2,(500-img.height*scale)/2,img.width*scale,img.height*scale);hasInk=true});
$('saveDrawing').onclick=()=>{if(!hasInk)return toast('先画点东西');const a=document.createElement('a');a.download='weapon-sketch.png';a.href=canvas.toDataURL();a.click()};
$('experience').onclick=()=>show('wait');
$('addSample').onclick=safe(async()=>{await ready;const button=$('addSample');button.disabled=true;try{const failed=$('outcome').value==='failed',file=$('modelFile').files[0];if(!failed&&!file)throw Error('成功记录需要一个真实 GLB 模型');if(file&&file.size>40*1024*1024)throw Error('请使用小于 40 MB 的 GLB');if(!failed){const header=new Uint8Array(await file.slice(0,4).arrayBuffer());if(String.fromCharCode(...header)!=='glTF')throw Error('文件不是有效 GLB')}
if(!$('seconds').value||Number($('seconds').value)<=0)throw Error('请填写实际耗时');if($('inputType').value==='image'&&!hasInk)throw Error('图生记录请先画图或上传参考图');const code=$('sampleId').value.trim()||`W${String(state.samples.length+1).padStart(3,'0')}`;if(state.samples.some(s=>s.code===code))throw Error('编号已存在');
const s={id:crypto.randomUUID(),code,blind:'样本 '+crypto.randomUUID().slice(0,6),created:new Date().toISOString(),subject:$('subject').value,prompt:$('prompt').value,input:$('inputType').value,tier:$('tier').value,seconds:Number($('seconds').value),credits:$('credits').value===''?null:Number($('credits').value),outcome:failed?'failed':'success',notes:$('notes').value,reference:hasInk?canvas.toDataURL():null,model:failed?null:await readFile(file),screenshot:$('shotFile').files[0]?await readFile($('shotFile').files[0]):null,votes:{}};
if(!Number.isFinite(s.seconds)||s.seconds<=0||s.credits!==null&&(!Number.isFinite(s.credits)||s.credits<0))throw Error('耗时和积分必须为有效非负数');state.samples.push(s);try{await save()}catch(e){state.samples.pop();throw e}refreshSources();$('sampleId').value='';$('modelFile').value='';$('shotFile').value='';toast('真实记录已保存')}finally{button.disabled=false}});
function refreshSources(){const sel=$('revealSource');while(sel.options.length>1)sel.remove(1);state.samples.filter(s=>s.model).forEach(s=>sel.add(new Option(s.code,s.id)))}
function viewer(data){const v=document.createElement('model-viewer');v.src=data;v.alt='待评武器模型';v.setAttribute('camera-controls','');v.setAttribute('auto-rotate','');v.setAttribute('touch-action','pan-y');v.addEventListener('error',()=>toast('模型加载失败，请检查 GLB 文件'));return v}
function reveal(source){$('reveal').replaceChildren();const s=state.samples.find(s=>s.id===source);if(s?.model){$('reveal').append(viewer(s.model));$('stageTitle').textContent='武器出炉';$('stageLine').textContent='预先生成的真实模型 · 非本次实时生成'}else{$('stageTitle').textContent='传说级 · 加班之锤';$('stageLine').textContent='“伤害未知，催稿效果拔群。”（预写台词）';const p=document.createElement('p');p.textContent='🔨';p.style.fontSize='80px';$('reveal').append(p);const note=document.createElement('p');note.className='small';note.textContent='演出样例 · 非 Lux3D 生成 / 非 AI 鉴定';$('reveal').append(note)}}
function lockWait(b){['startWait','tester','duration','presentation','revealSource'].forEach(id=>$(id).disabled=b);$('cancelWait').hidden=!b}
function beginWait(replay=false){if(run)return;const tester=$('tester').value.trim();if(!tester)return toast('请填写测试者代号');pending=null;$('feedback').hidden=true;$('reveal').replaceChildren();const seconds=Number($('duration').value),presentation=$('presentation').value;run={id:crypto.randomUUID(),tester,seconds,presentation,source:$('revealSource').value,started:new Date().toISOString(),start:performance.now(),interrupted:false,replay};lockWait(true);$('stage').classList.toggle('running',presentation==='ritual');$('stage').classList.toggle('plain',presentation==='plain');$('forge').textContent=presentation==='ritual'?'✳':'◌';$('stageTitle').textContent=presentation==='ritual'?'正在锻造':'正在等待';$('progress').hidden=presentation==='ritual';tick()}
function tick(){if(!run)return;const elapsed=(performance.now()-run.start)/1000,ratio=Math.min(elapsed/run.seconds,1);$('progress').value=ratio;const lines=['正在收集一点离谱的灵感…','形状越古怪，出场越嚣张。','锤炼中。它似乎有自己的想法。','鉴定员正在努力保持严肃。','准备揭晓。你的武器要来了。'];$('stageLine').textContent=run.presentation==='ritual'?lines[Math.min(4,Math.floor(ratio*5))]:'正在处理，请稍候…';if(ratio>=1){pending={...run,actualSeconds:elapsed,completed:true};delete pending.start;run=null;lockWait(false);$('stage').classList.remove('running');reveal(pending.source);$('feedback').hidden=false;return}setTimeout(tick,100)}
$('startWait').onclick=()=>beginWait();$('cancelWait').onclick=safe(async()=>{if(!run)return;const record={...run,actualSeconds:(performance.now()-run.start)/1000,completed:false};delete record.start;run=null;lockWait(false);$('stage').classList.remove('running');state.waits.push(record);await save();$('stageTitle').textContent='已退出';$('stageLine').textContent='中途退出已留痕。'});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&run)run.interrupted=true});
async function feedback(){if(!pending)return false;state.waits.push({...pending,feeling:$('feeling').value,again:$('again').value});await save();pending=null;$('feedback').hidden=true;toast('体验反馈已记录');return true}
$('saveFeedback').onclick=safe(feedback);$('replay').onclick=safe(async()=>{if(!pending)return;pending.activeReplay=true;if(await feedback())beginWait(true)});
function review(){const who=$('reviewer').value;const candidates=state.samples.filter(s=>s.outcome==='success'&&s.model&&!s.votes[who]);if(!candidates.length){current=null;$('reviewBody').textContent='没有待评模型。先录入真实生成，或切换评审身份。';return}current=candidates[Math.floor(Math.random()*candidates.length)];const root=$('reviewBody');root.replaceChildren();const article=document.createElement('article');const h=document.createElement('h2');h.textContent=current.blind;article.append(h,viewer(current.model));if(current.screenshot){const image=document.createElement('img');image.src=current.screenshot;image.alt='模型截图';article.append(image)}
const options=[['recognize','能认出是什么'],['battle','能想象拿它打架']];for(const [id,label] of options){const l=document.createElement('label');l.textContent=label;const sel=document.createElement('select');sel.id=id;sel.add(new Option('请选择',''));sel.add(new Option('是','yes'));sel.add(new Option('否','no'));l.append(sel);article.append(l)}const b=document.createElement('button');b.textContent='提交评分';b.className='primary';b.onclick=safe(async()=>{if(!$('recognize').value||!$('battle').value)return toast('请回答两项');current.votes[who]={recognize:$('recognize').value==='yes',battle:$('battle').value==='yes',at:new Date().toISOString()};await save();review()});article.append(b);root.append(article)}
$('reviewer').onchange=review;$('nextReview').onclick=review;
function counts(){const group=state.samples.filter(s=>s.input==='text'&&s.tier==='fast');let complete=true,passed=0,used=0;for(const [,sub] of subjects){const slots=group.filter(s=>s.subject===sub).sort((a,b)=>a.created.localeCompare(b.created)).slice(0,3);used+=slots.length;if(slots.length<3)complete=false;for(const s of slots){if(s.outcome==='failed')continue;if(!['A','B','C'].every(w=>s.votes[w]))complete=false;if(['A','B','C'].filter(w=>s.votes[w]?.recognize&&s.votes[w]?.battle).length>=2)passed++}}return {used,passed,complete:complete&&used===30}}
function report(){const c=counts(),valid=state.waits.filter(w=>w.completed&&!w.interrupted);const root=$('stats');root.replaceChildren();const metrics=document.createElement('div');metrics.className='metrics';for(const [value,label] of [[`${c.used}/30`,'主实验记录（固定每主体前三次）'],[c.complete?`${Math.round(c.passed/30*100)}%`:'待完成','三人盲评可用率'],[c.complete?(c.passed>=18?'GO':'NO-GO'):'尚不判定','质量假设']]){const div=document.createElement('div');div.className='metric';const strong=document.createElement('strong');strong.textContent=value;const text=document.createElement('span');text.textContent=label;div.append(strong,text);metrics.append(div)}root.append(metrics);const a=document.createElement('article');a.style.marginTop='20px';const h=document.createElement('h2');h.textContent='等待体验 · 观察结果';a.append(h);for(const kind of ['ritual','plain']){const arr=valid.filter(w=>w.presentation===kind);const p=document.createElement('p');p.textContent=`${kind==='ritual'?'锻造演出':'普通等待'}：有效 ${arr.length} 次 / 抽奖感 ${arr.filter(w=>w.feeling==='draw').length} / 卡顿感 ${arr.filter(w=>w.feeling==='stuck').length} / 主动复玩 ${arr.filter(w=>w.activeReplay).length}`;a.append(p)}const note=document.createElement('p');note.className='small';note.textContent=`中途退出 ${state.waits.filter(w=>!w.completed).length} 次；切后台无效 ${state.waits.filter(w=>w.interrupted).length} 次。重复测试不等于独立测试者，详见导出明细。`;a.append(note);root.append(a);const article=document.createElement('article');const heading=document.createElement('h2');heading.textContent='真实生成台账';article.append(heading);const wrap=document.createElement('div');wrap.className='table-wrap';const table=document.createElement('table');const head=document.createElement('tr');for(const text of ['编号','主体','方式 / 档位','结果','秒','积分','评分']){const th=document.createElement('th');th.textContent=text;head.append(th)}table.append(head);state.samples.forEach(s=>{const tr=document.createElement('tr');for(const text of [s.code,subjects.find(x=>x[1]===s.subject)?.[0]||s.subject,`${s.input} / ${s.tier}`,s.outcome,s.seconds,s.credits??'未填',Object.keys(s.votes).length+'/3']){const td=document.createElement('td');td.textContent=text;tr.append(td)}table.append(tr)});wrap.append(table);article.append(wrap);root.append(article)}
$('export').onclick=safe(async()=>{await ready;download('huagechuizi-backup-'+Date.now()+'.json',JSON.stringify(state));toast('备份已导出，含模型与评分')});
$('import').onchange=safe(async e=>{const file=e.target.files[0];if(!file)return;const incoming=JSON.parse(await file.text());if(incoming.version!==1||!Array.isArray(incoming.samples)||!Array.isArray(incoming.waits))throw Error('备份格式错误');for(const s of incoming.samples){if(typeof s.id!=='string'||!s.votes||!['text','image'].includes(s.input)||!['fast','standard'].includes(s.tier)||!['success','failed'].includes(s.outcome)||!Number.isFinite(s.seconds)||s.seconds<0||s.model&&!/^data:(model\/gltf-binary|application\/octet-stream|);base64,/.test(s.model)||s.screenshot&&!/^data:image\/(png|jpeg|webp);base64,/.test(s.screenshot))throw Error('备份含无效样本')}for(const w of incoming.waits){if(typeof w.id!=='string'||!['ritual','plain'].includes(w.presentation))throw Error('备份含无效等待记录')}
const merged=structuredClone(state);for(const s of incoming.samples){const old=merged.samples.find(x=>x.id===s.id);if(old)old.votes={...old.votes,...s.votes};else merged.samples.push(s)}for(const w of incoming.waits){const i=merged.waits.findIndex(x=>x.id===w.id);if(i<0)merged.waits.push(w);else merged.waits[i]=w}const before=state;state=merged;try{await save()}catch(e){state=before;throw e}refreshSources();report();toast('备份已合并');e.target.value=''});
$('csv').onclick=()=>{const quote=v=>'"'+String(v??'').replace(/^[=+@-]/,"'").replaceAll('"','""')+'"';const rows=[['type','id','subject/tester','prompt/presentation','tier/seconds','outcome','seconds/actual','credits','A','B','C','notes/feeling','again','activeReplay','interrupted']];state.samples.forEach(s=>rows.push(['generation',s.code,s.subject,s.prompt,s.tier,s.outcome,s.seconds,s.credits,...['A','B','C'].map(w=>s.votes[w]?JSON.stringify(s.votes[w]):''),s.notes]));state.waits.forEach(w=>rows.push(['wait',w.id,w.tester,w.presentation,w.seconds,w.completed,w.actualSeconds,'','','','',w.feeling,w.again,w.activeReplay,w.interrupted]));download('huagechuizi-records.csv','\ufeff'+rows.map(r=>r.map(quote).join(',')).join('\r\n'),'text/csv;charset=utf-8')};
ready.then(refreshSources).catch(()=>toast('浏览器存储不可用，请退出隐私模式再打开'));
